(function(){
  var G=Arena.Game,W=G.world;G._running=false;
  var p=W.getPlayer();
  var e=W.entities.filter(function(x){return x.id!==p.id;})[0];
  var M=Arena.Sim.ArenaMetrics;
  var sitio=null;
  for(var d=14; d>=5 && !sitio; d-=1){
    for(var a=0; a<12 && !sitio; a++){
      var ang=a*Math.PI/6;
      var ax=Math.cos(ang)*2, az=Math.sin(ang)*2;
      var bx=Math.cos(ang)*(2+d), bz=Math.sin(ang)*(2+d);
      if(M.walkable(W.arena,ax,az,0.5) && M.walkable(W.arena,bx,bz,0.5) &&
         M.losBetween(W.arena,{x:ax,y:1,z:az},{x:bx,y:1,z:bz}))
        sitio={ax:ax,az:az,bx:bx,bz:bz,dist:d};
    }
  }
  window.__sitio=sitio;
  function coloca(){
    p.pos.x=sitio.ax;p.pos.z=sitio.az;p.pos.y=0;p.resource=p.resourceMax;
    p.alive=true;p.hp=p.hpMax;p.cooldowns=Object.create(null);p.gcdUntil=-999;
    e.pos.x=sitio.bx;e.pos.z=sitio.bz;e.pos.y=0;e.hpMax=200000;e.hp=200000;e.alive=true;
    p.yaw=Math.atan2(e.pos.x-p.pos.x, e.pos.z-p.pos.z);
    p.targetId=e.id;
  }
  window.__coloca=coloca;
  window.__jugador=function(){return p;};
  window.__enemigo=function(){return e;};
  window.__proyectiles=function(){
    var AB=Arena.Data.abilities, out=[];
    for(var k in AB){ var ab=AB[k];
      if(ab&&ab.flags&&ab.flags.projectile&&ab.target==='enemy'&&ab.classId===p.classId&&ab.range>=sitio.dist) out.push(k); }
    return out;
  };
  return sitio? 'listo d='+sitio.dist : 'SIN SITIO';
})()

(function(){
  var W=Arena.Game.world, AB=Arena.Data.abilities;
  var p=window.__jugador(), lista=window.__proyectiles();
  if(!window.__sitio) return {assert:false,fail:['no hay par con línea de visión en la arena']};
  if(!lista.length) return {assert:false,fail:['la clase no tiene proyectil a enemigo dentro de alcance']};
  var res=[], fallos=[];
  for(var n=0;n<Math.min(6,lista.length);n++){
    var id=lista[n], ab=AB[id];
    window.__coloca();
    var spawns=0, rechazo=null;
    var o1=W.bus.on('ProjectileSpawned',function(){spawns++;});
    var o2=W.bus.on('AbilityRejected',function(x){ if(!rechazo) rechazo=x.reason; });
    var r=Arena.Combat.AbilitySystem.tryUse(W,p,id,{targetId:window.__enemigo().id, target:window.__enemigo()});
    for(var t=0;t<140;t++) W.step();
    o1();o2();
    res.push(ab.name+' ok='+(r&&r.ok)+' spawns='+spawns);
    if(!(r&&r.ok)) fallos.push(ab.name+' rechazada por '+rechazo);
    else if(spawns===0) fallos.push(ab.name+': RELEASE sin proyectil');
  }
  return {assert:!fallos.length, fail:fallos, probadas:res.length, resultados:res};
})()

(function(){
  var W=Arena.Game.world, AB=Arena.Data.abilities;
  var p=window.__jugador(), e=window.__enemigo(), lista=window.__proyectiles();
  if(!lista.length) return {assert:false,fail:['sin habilidad de proyectil que probar']};
  window.__coloca();
  var r=Arena.Combat.AbilitySystem.tryUse(W,p,lista[0],{targetId:e.id,target:e});
  if(!(r&&r.ok)) return {assert:false,fail:['la habilidad no se pudo usar: '+(r&&r.reason)]};
  var t=0;
  while(t<200 && W.projectiles.length===0){ W.step(); t++; }
  if(!W.projectiles.length) return {assert:false,fail:['no llegó a haber proyectil en vuelo']};
  var antes=W.projectiles.length;
  p.hp=0; p.alive=false;
  W.step();
  var despues=W.projectiles.length;
  var ok = despues>=antes;
  return {assert:ok,
    fail: ok?[]:['RELEASE es irreversible: el proyectil ya liberado se borró al morir el lanzador ('+antes+' -> '+despues+')'],
    habilidad:AB[lista[0]].name, antesDeMorir:antes, despuesDeMorir:despues, ticksHastaVuelo:t};
})()
